CREATE TABLE "PlatformOperator"("userId" TEXT PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('support','platform_admin')),"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SupportGrant"(id TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "Organization"(id) ON DELETE CASCADE,"operatorUserId" TEXT NOT NULL REFERENCES "PlatformOperator"("userId"),"approvedBy" TEXT NOT NULL REFERENCES "User"(id),reason TEXT NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 2000),scopes TEXT[] NOT NULL CHECK(cardinality(scopes) BETWEEN 1 AND 4 AND scopes <@ ARRAY['catalog.read','inventory.read','sales.read','diagnostics.read']::text[]),"storeIds" TEXT[] NOT NULL CHECK(cardinality("storeIds") BETWEEN 1 AND 20),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"revokedBy" TEXT REFERENCES "User"(id),CHECK("expiresAt">"createdAt" AND "expiresAt"<="createdAt"+INTERVAL '1 hour'),CHECK(("revokedAt" IS NULL)=("revokedBy" IS NULL)));
CREATE INDEX "SupportGrant_organizationId_createdAt_id_idx" ON "SupportGrant"("organizationId","createdAt",id);
CREATE INDEX "SupportGrant_operatorUserId_expiresAt_idx" ON "SupportGrant"("operatorUserId","expiresAt");
CREATE FUNCTION support_grant_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN IF NOT EXISTS(SELECT 1 FROM "Organization" WHERE id=OLD."organizationId") THEN RETURN OLD;END IF;RAISE EXCEPTION 'Support grants are retained; revoke instead';END IF;
 IF TG_OP='UPDATE' THEN
 IF (NEW.id,NEW."organizationId",NEW."operatorUserId",NEW."approvedBy",NEW.reason,NEW.scopes,NEW."storeIds",NEW."createdAt",NEW."expiresAt") IS DISTINCT FROM (OLD.id,OLD."organizationId",OLD."operatorUserId",OLD."approvedBy",OLD.reason,OLD.scopes,OLD."storeIds",OLD."createdAt",OLD."expiresAt") OR OLD."revokedAt" IS NOT NULL OR NEW."revokedAt" IS NULL THEN RAISE EXCEPTION 'Support grant approval immutable';END IF;
 IF NOT EXISTS(SELECT 1 FROM "OrganizationUser" m JOIN "User" u ON u.id=m."userId" WHERE m."organizationId"=NEW."organizationId" AND m."userId"=NEW."revokedBy" AND m.role='owner' AND m."isActive" AND u."isActive") THEN RAISE EXCEPTION 'Support revocation requires live owner';END IF;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM "OrganizationUser" m JOIN "User" u ON u.id=m."userId" WHERE m."organizationId"=NEW."organizationId" AND m."userId"=NEW."approvedBy" AND m.role='owner' AND m."isActive" AND u."isActive") THEN RAISE EXCEPTION 'Support consent requires live owner';END IF;
 IF NOT EXISTS(SELECT 1 FROM "PlatformOperator" o JOIN "User" u ON u.id=o."userId" WHERE o."userId"=NEW."operatorUserId" AND o."isActive" AND u."isActive") THEN RAISE EXCEPTION 'Active platform operator required';END IF;
 IF EXISTS(SELECT 1 FROM unnest(NEW."storeIds") sid WHERE NOT EXISTS(SELECT 1 FROM "Store" s WHERE s.id=sid AND s."organizationId"=NEW."organizationId" AND s."isActive")) THEN RAISE EXCEPTION 'Support grant branch scope mismatch';END IF;
 IF cardinality(NEW.scopes)<>(SELECT count(DISTINCT value) FROM unnest(NEW.scopes) value) OR cardinality(NEW."storeIds")<>(SELECT count(DISTINCT value) FROM unnest(NEW."storeIds") value) THEN RAISE EXCEPTION 'Duplicate grant scope';END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER support_grant_guard BEFORE INSERT OR UPDATE OR DELETE ON "SupportGrant" FOR EACH ROW EXECUTE FUNCTION support_grant_guard();
